"use strict";

// Native ANSI color codes (no dependencies)
const ANSI = {
  // Reset
  reset: '\x1b[0m',
  // Foreground colors (8-bit)
  black: '\x1b[30m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
  white: '\x1b[37m',
  gray: '\x1b[90m',
  brightRed: '\x1b[91m',
  brightGreen: '\x1b[92m',
  brightYellow: '\x1b[93m',
  brightBlue: '\x1b[94m',
  brightMagenta: '\x1b[95m',
  brightCyan: '\x1b[96m',
  brightWhite: '\x1b[97m',
  // Background colors
  bgBlack: '\x1b[40m',
  bgRed: '\x1b[41m',
  bgGreen: '\x1b[42m',
  bgYellow: '\x1b[43m',
  bgBlue: '\x1b[44m',
  bgMagenta: '\x1b[45m',
  bgCyan: '\x1b[46m',
  bgWhite: '\x1b[47m',
  // Cursor controls
  hideCursor: '\x1b[?25l',
  showCursor: '\x1b[?25h',
  cursorToStart: '\x1b[0G', // Cursor to column 0
  clearLine: '\x1b[2K',     // Clear current line
  // 24-bit RGB (true color)
  rgb: (r, g, b) => `\x1b[38;2;${r};${g};${b}m`,
  bgRgb: (r, g, b) => `\x1b[48;2;${r};${g};${b}m`
};

// Famous colors users commonly use (hex to RGB mapping for easy access)
const COLORS = {
  // Standard 16 colors
  black: { r: 0, g: 0, b: 0 },
  red: { r: 255, g: 0, b: 0 },
  green: { r: 0, g: 128, b: 0 },
  yellow: { r: 255, g: 255, b: 0 },
  blue: { r: 0, g: 0, b: 255 },
  magenta: { r: 255, g: 0, b: 255 },
  cyan: { r: 0, g: 255, b: 255 },
  white: { r: 255, g: 255, b: 255 },
  gray: { r: 128, g: 128, b: 128 },
  // Popular theme colors (e.g., from chalk, terminal themes)
  brightRed: { r: 255, g: 23, b: 68 },
  brightGreen: { r: 0, g: 255, b: 0 },
  brightYellow: { r: 255, g: 193, b: 7 },
  brightBlue: { r: 0, g: 122, b: 255 },
  brightMagenta: { r: 255, g: 0, b: 255 },
  brightCyan: { r: 64, g: 224, b: 208 },
  brightWhite: { r: 255, g: 255, b: 255 },
  // Additional famous ones (e.g., orange, purple, lime, etc.)
  orange: { r: 255, g: 165, b: 0 },
  purple: { r: 128, g: 0, b: 128 },
  lime: { r: 50, g: 205, b: 50 },
  pink: { r: 255, g: 192, b: 203 },
  teal: { r: 0, g: 128, b: 128 },
  indigo: { r: 75, g: 0, b: 130 },
  // Hex to RGB helper (users can pass hex like '#ff0000')
  fromHex: (hex) => {
    hex = hex.replace('#', '');
    const r = parseInt(hex.substr(0, 2), 16);
    const g = parseInt(hex.substr(2, 2), 16);
    const b = parseInt(hex.substr(4, 2), 16);
    return { r, g, b };
  }
};

// Built-in ASCII art library (searchable by keyword)
const ASCII_ARTS = {
  // Animals
  cat: `
 /\\_/\\  
( o.o ) 
 > ^ < 
  `,
  dog: `
  / \\__
 (    @\\___
 /         O
/   (_____/
/_____/   U
  `,
  // Emojis/Emoticons
  smile: `
  ^ ^
 (   )
  \\_/
  `,
  heart: `
 ***   ***
***** *****
***********
 **** *****
  **   **
  `,
  // Tech/Logos (simple)
  rocket: `
   /\\
  |oo|
  |~~|
 /|__\\\\
  `,
  star: `
   *
  ***
 *****
*******
 *****
  ***
   *
  `,
  // Welcome/Generic
  welcome: `
  _____
 /     \\
|  O O  |
 \\  ^  /
  |||||
  `,
  loading: `
  .
 ..
 ...
  `,
  // Add more as needed (users can add dynamically)
};

// Options for console features
const options = {
  animate: false,
  duration: 12,
  seed: 0,
  speed: 20, // ms per frame
  spread: 8.0,
  freq: 0.3,
  debug: false,
  // Default color for prints
  defaultColor: 'cyan'
};

// Rainbow generator (same as example, but native)
const rainbow = function(freq, i) {
  const red = Math.round(Math.sin(freq * i + 0) * 127 + 128);
  const green = Math.round(Math.sin(freq * i + 2 * Math.PI / 3) * 127 + 128);
  const blue = Math.round(Math.sin(freq * i + 4 * Math.PI / 3) * 127 + 128);
  return { r: red, g: green, b: blue };
};

// Colorize a single character with RGB or named color
const colorizeChar = function(char, color) {
  let code;
  if (typeof color === 'string') {
    if (ANSI[color]) {
      code = ANSI[color];
    } else {
      const rgb = COLORS.fromHex(color) || COLORS[options.defaultColor];
      code = ANSI.rgb(rgb.r, rgb.g, rgb.b);
    }
  } else if (typeof color === 'object' && color.r !== undefined) {
    code = ANSI.rgb(color.r, color.g, color.b);
  } else {
    code = ANSI.reset; // Fallback
  }
  process.stdout.write(code + char + ANSI.reset);
};

// Print a line with plain colors (supports named, hex, or rainbow)
const printlnPlain = function(line, colorMode = 'default') {
  if (colorMode === 'rainbow') {
    for (let i = 0; i < line.length; i++) {
      const colors = rainbow(options.freq, options.seed + i / options.spread);
      colorizeChar(line[i], colors);
    }
  } else {
    const color = colorMode || options.defaultColor;
    for (let i = 0; i < line.length; i++) {
      colorizeChar(line[i], color);
    }
  }
  process.stdout.write('\n');
};

// Animated print (uses setTimeout for sleep simulation, no dep needed)
const printlnAnimated = function(line, colorMode = 'default') {
  if (options.animate && typeof setTimeout !== 'undefined') {
    const seed = options.seed;
    let frame = 0;
    const animateFrame = () => {
      process.stdout.write(ANSI.clearLine + ANSI.cursorToStart);
      options.seed += options.spread;
      printlnPlain(line, colorMode);
      frame++;
      if (frame < options.duration) {
        setTimeout(animateFrame, 1000 / options.speed);
      } else {
        options.seed = seed;
        process.stdout.write('\n');
      }
    };
    animateFrame();
  } else {
    printlnPlain(line, colorMode);
    process.stdout.write('\n');
  }
};

// Main print function
const println = function(line, opts = {}) {
  const { animate = options.animate, color = options.defaultColor } = opts;
  process.stdout.write(ANSI.showCursor);
  if (animate) {
    process.stdout.write(ANSI.hideCursor);
    printlnAnimated(line, color);
  } else {
    printlnPlain(line, color);
  }
  process.stdout.write(ANSI.showCursor + '\n');
};

// Search and print ASCII art
const printArt = function(keyword, color = 'yellow') {
  const art = searchArt(keyword);
  if (art) {
    const lines = art.split('\n');
    lines.forEach(line => {
      printlnPlain(line, color);
    });
  } else {
    console.log(`No ASCII art found for "${keyword}". Use addArt() to add one.`);
  }
};

// Search ASCII art by keyword (simple string match)
const searchArt = function(keyword) {
  for (const [key, art] of Object.entries(ASCII_ARTS)) {
    if (key.includes(keyword.toLowerCase()) || art.toLowerCase().includes(keyword.toLowerCase())) {
      return art;
    }
  }
  return null;
};

// Add custom ASCII art (dynamic, persists in memory)
const addArt = function(keyword, art) {
  ASCII_ARTS[keyword.toLowerCase()] = art;
  if (options.debug) {
    console.log(`Added ASCII art for "${keyword}"`);
  }
};

// Input handlers (adapted without deps; uses process.stdin directly)
const fromPipe = function() {
  return new Promise((resolve) => {
    process.stdin.resume();
    process.stdin.setEncoding('utf8');
    let data = '';
    process.stdin.on('data', chunk => {
      data += chunk;
    });
    process.stdin.on('end', () => {
      const lines = data.split('\n').filter(l => l.trim());
      lines.forEach(line => {
        options.seed += 1;
        println(line);
      });
      resolve();
    });
  });
};

const fromFile = function(filePath) {
  return new Promise((resolve, reject) => {
    const fs = require('fs');
    if (!fs.existsSync(filePath)) {
      reject(new Error(`File not found: ${filePath}`));
      return;
    }
    const stream = fs.createReadStream(filePath, { encoding: 'utf8' });
    let lineCount = 0;
    stream.on('data', chunk => {
      const lines = chunk.toString().split('\n');
      lines.forEach(line => {
        if (line.trim()) {
          options.seed += 1;
          println(line);
          lineCount++;
        }
      });
    });
    stream.on('end', () => resolve(lineCount));
    stream.on('error', reject);
  });
};

const fromString = function(str, opts = {}) {
  const lines = (str || '').split('\n').filter(l => l.trim());
  lines.forEach(line => {
    options.seed += 1;
    println(line, opts);
  });
};

// Init (no deps needed now)
const init = function() {
  // Set default color if provided
  if (process.env.MOVANEST_DEFAULT_COLOR) {
    options.defaultColor = process.env.MOVANEST_DEFAULT_COLOR;
  }
  return null;
};

// Exports (no module naming wrapper here; direct exports for mova integration)
module.exports = {
  // Core
  println,
  options,
  init,
  // Colors
  ANSI,
  COLORS,
  // ASCII
  printArt,
  searchArt,
  addArt,
  ASCII_ARTS,
  // Rainbow
  rainbow,
  // Inputs
  fromPipe,
  fromFile,
  fromString
};
